.dg-render-scope[data-system="MGC"] .prev_terms .terms_btn a.open .ico_arr{background:url(../../core/MGC/assets/localgift/img/terms_pop_arr_open.png) no-repeat 0 0;background-size:10px 6px;}
.dg-render-scope[data-system="MGC"] .prev_terms .list{position:absolute;left:0;top:40px;padding:0 20px;width:100%;box-sizing:border-box;background-color:#fff;}
.dg-render-scope[data-system="MGC"] .prev_terms .list.show_top{top:auto;bottom:39px}
.dg-render-scope[data-system="MGC"] .prev_terms .list.show_top ul{border-top:1px solid #eee;}
.dg-render-scope[data-system="MGC"] .prev_terms .list ul{border:1px solid #eee;border-top:0 none;}
.dg-render-scope[data-system="MGC"] .prev_terms .list li a{display:block;3px;font-family:'NanumSquareAcR';color:#666;padding:10px 14px;}
.dg-render-scope[data-system="MGC"] .layer_pop_tit{font-size:18px;font-family:'NanumSquareAcB';color:#222;font-weight:400;}
.dg-render-scope[data-system="MGC"] .termsPolicy .btn, .dg-render-scope[data-system="MGC"] .layer_terms .btn{padding:20px 20px;display:flex;flex-direction:row;background-color:#fff;}
.dg-render-scope[data-system="MGC"] .layer_terms .btn a, .dg-render-scope[data-system="MGC"] .termsPolicy .btn a{display:block;font-size:15px;font-family:'NanumSquareAcB';color:#fff;font-weight:400;width:100%;padding:13px 0 12px;text-align:center;background-color:#0C419A;}
.dg-render-scope[data-system="MGC"] .termsPolicy .btns, .dg-render-scope[data-system="MGC"] .pop_style_tit .btns{padding:20px 20px;display:flex;flex-direction:row;justify-content:space-between;}
.dg-render-scope[data-system="MGC"] .termsPolicy .btns a, .dg-render-scope[data-system="MGC"] .pop_style_tit .btns a{display:block;font-size:15px;font-family:'NanumSquareAcB';color:#fff;font-weight:400;width:calc(50% - 4px);padding:15px 0 14px;text-align:center;background-color:#0C419A;border:1px solid #0C419A;box-sizing:border-box;border-radius:8px;}
.dg-render-scope[data-system="MGC"] .termsPolicy .btns a.btn_cancel, .dg-render-scope[data-system="MGC"] .pop_style_tit .btns a.btn_cancel{border:1px solid #E7E7E7;color:#222;background-color:#E7E7E7;}
.dg-render-scope[data-system="MGC"] .pop_style_tit .top_bx{padding-top: 31px;}
.dg-render-scope[data-system="MGC"] .pop_style_tit .top_bx .pop_close_btn{top:10px;right:11px;}
.dg-render-scope[data-system="MGC"] .pop_style_tit .inner{padding:0 20px 7px;overflow-y:auto;height: calc(100% - 130px);}
.dg-render-scope[data-system="MGC"] .pop_style_tit .inner p{font-size:14px;font-family:'NanumSquareAcR';color:#222;line-height:1.5;}
.dg-render-scope[data-system="MGC"] .pop_style_tit .inner p strong{font-size:14px;font-family:'NanumSquareAcB';font-weight:400;}
.dg-render-scope[data-system="MGC"] .layeroverlay{z-index:999;position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0, 0.16);}
.dg-render-scope[data-system="MGC"] .layer_pop_w{display:flex;flex-direction:row;height:100%;box-sizing:border-box;}
.dg-render-scope[data-system="MGC"] .layer_bpop{align-self:flex-end;background-color:#fff;flex-grow:1;border-radius:24px 24px 0 0;}
.dg-render-scope[data-system="MGC"] .gift_sel{max-height:350px;box-sizing:border-box;}
.dg-render-scope[data-system="MGC"] .layer_pop_w .top_bx{position:relative;padding:18px 20px 17px;}
.dg-render-scope[data-system="MGC"] .layer_pop_w .top_bx p{font-size:13px;font-family:'NanumSquareB';color:#222;}
.dg-render-scope[data-system="MGC"] .layer_pop_w .pop_close_btn{position:absolute;top:13px;right:18px;}
.dg-render-scope[data-system="MGC"] .layer_pop_w .pop_close_btn a{display:block;text-indent:-99999px;background:url(../../core/MGC/assets/localgift/img/store/layer_pop_close.png) no-repeat center center;background-size:15px 15px;width:28px;height:28px;}
.dg-render-scope[data-system="MGC"] .layer_bpop .gift_select_bx{padding:0 10px;overflow-y:auto;max-height:299px;}
.dg-render-scope[data-system="MGC"] .layer_bpop .gift_select_bx::-webkit-scrollbar{display:none;}
.dg-render-scope[data-system="MGC"] .layer_bpop .gift_select{display:flex;flex-direction:column;}
.dg-render-scope[data-system="MGC"] .layer_bpop .gift_select li{margin-top:2px;}
.dg-render-scope[data-system="MGC"] .layer_bpop .gift_select li:first-child{margin-top:0;}
.dg-render-scope[data-system="MGC"] .layer_bpop .gift_select li a{display:block;font-size:14px;font-family:'NanumSquareR';color:#222;vertical-align:middle;line-height:44px;padding-left:45px;background-color:#f7f7f7;background-image:url(../../core/MGC/assets/localgift/img/store/ico_gift_sel.png);background-repeat:no-repeat;background-position:22px center;background-size:16px 11px;}
.dg-render-scope[data-system="MGC"] .layer_bpop .gift_select li a.on{font-family:'NanumSquareB';background-image:url(../../core/MGC/assets/localgift/img/store/ico_gift_sel_on.png);background-color:#e9ebfd;}
.dg-render-scope[data-system="MGC"] .termsPolicy .bot_fix{position:absolute;bottom:0;left:0;right:0;padding:10px 20px;}
.dg-render-scope[data-system="MGC"] .fc_key_color{color:#5B6BEE !important;}
.dg-render-scope[data-system="MGC"] .pd_lr20{padding:0 20px !important;}
.dg-render-scope[data-system="MGC"] .full_height{height:100%;}
.dg-render-scope[data-system="MGC"] .full_height .container{height:calc(100% - 52px);padding-top:52px;}
.dg-render-scope[data-system="MGC"] .full_height .content{height:100%}
.dg-render-scope[data-system="MGC"] .bg_white{background-color:#fff !important;}
.dg-render-scope[data-system="MGC"] .txt_r{color:#f00 !important;}
.dg-render-scope[data-system="MGC"] .fw_eb{font-family:'NanumSquareEB';}
.dg-render-scope[data-system="MGC"] .page_moving{display:-webkit-box;display:-moz-box;display:-ms-flexbox;display:-webkit-flex;display:flex;flex-flow:column nowrap;justify-content:center;align-items:center;text-align:center;height:calc(100% - 252px);}
.dg-render-scope[data-system="MGC"] .page_moving img{width:300px;height:auto;}
.dg-render-scope[data-system="MGC"] .page_moving p{margin-top:16px;padding:3px 0 1px;font-size:18px;font-family:'NanumSquareEB';color:#222;line-height:normal;}
/* 울타리를 기준 상자로 삼는다 — 위에서 absolute 로 옮긴 것들이 여기에 붙는다. */
.dg-render-scope[data-system="MGC"]{position:relative}
